        "confidence": 0.95
      }
    },
    {
      "id": "sub2.example.org",
      "type": "domain",
      "context_attributes": {
        "relationship_type": "subdomain_of",
        "confidence": 0.90
      }
    },
    {
      "id": "sub3.example.org",
      "type": "domain",
      "context_attributes": {
        "relationship_type": "subdomain_of",
        "confidence": 0.85
      }
    }
